#include <stdio.h>

int main() {
    int L, C, P;
    if (scanf("%d %d", &L, &C) != 2) return 0;
    scanf("%d", &P);

    int black[6][6] = {0};
    for (int i = 0; i < P; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        black[x - 1][y - 1] = 1;
    }

    int cand[6] = {0};
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            if (black[r][c]) continue;

            int ok = 0;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
                    ok = 1;
                    break;
                }
            }

            if (ok) cand[r] |= (1 << c);
        }
    }

    int maxMask = 1 << C;
    int dp[64], ndp[64];

    for (int i = 0; i < maxMask; i++) dp[i] = -1000000;
    dp[0] = 0;

    for (int r = 0; r < L; r++) {
        for (int i = 0; i < maxMask; i++) ndp[i] = -1000000;

        for (int prev = 0; prev < maxMask; prev++) {
            if (dp[prev] < 0) continue;

            for (int mask = 0; mask < maxMask; mask++) {
                if ((mask & ~cand[r]) != 0) continue;
                if ((mask & (mask << 1)) != 0) continue;
                if ((mask & prev) != 0) continue;

                int val = dp[prev] + __builtin_popcount(mask);
                if (val > ndp[mask]) ndp[mask] = val;
            }
        }

        for (int i = 0; i < maxMask; i++) dp[i] = ndp[i];
    }

    int ans = 0;
    for (int i = 0; i < maxMask; i++) {
        if (dp[i] > ans) ans = dp[i];
    }

    printf("%d\n", ans);
    return 0;
}
